import {createReadCache} from './read-cache.js';
import {mountOfficialExam} from './official-exam.js';
import {speechSettings,wireSpeech,stopSpeech} from './speech.js';
import {languageSwitcher,startLanguageUi} from './i18n.js';
const $=s=>document.querySelector(s), root=$('#app');
startLanguageUi(root,document.querySelector('#toast'));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user=null,csrf='',meta={},cleanup=()=>{},routeVersion=0,loginPortal='employee';
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',learning:'M4 3h7v17H4z M11 5h9v17h-9 M6 7h3 M14 9h4',examination:'M7 4H4v18h16V4h-3 M8 2h8v5H8z M8 12h8 M8 16h5',ranking:'M7 3h10v6a5 5 0 0 1-10 0z M7 5H3v3a4 4 0 0 0 4 4 M17 5h4v3a4 4 0 0 1-4 4 M12 14v6 M7 21h10',profile:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0z M4 22v-3a8 8 0 0 1 16 0v3',employees:'M10 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0z M2 19v-3a5 5 0 0 1 10 0v3 M15 3a3 3 0 0 1 0 6 M15 12a5 5 0 0 1 6 5v2',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z M12 6v6l4 2',arrow:'M4 12h16 M14 6l6 6-6 6',logout:'M9 4H3v16h6 M9 12h12 M16 7l5 5-5 5'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(icons[k]||icons.dashboard).split(' M').map((p,i)=>`<path d="${i?'M':''}${p}"/>`).join('')}</svg>`;
const num=(v,d=0)=>v==null?'—':Number(v).toLocaleString('id-ID',{maximumFractionDigits:d});
const date=(t,short=false)=>new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Makassar',day:'numeric',month:short?'short':'long',year:short?undefined:'numeric'}).format(new Date(t*1000));
const fmtTime=s=>`${String(Math.floor(Math.max(0,s)/60)).padStart(2,'0')}:${String(Math.max(0,s)%60).padStart(2,'0')}`;
const badge=(text,color='')=>`<span class="pill ${color}">${esc(text)}</span>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
const readCache=createReadCache();
async function api(path,{method='GET',body}={}){if(method!=='GET')readCache.invalidate();const load=async()=>{let res;try{res=await fetch('/api'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)});}catch{throw Error('Koneksi terputus. Jawaban yang belum tersimpan akan dicoba kembali selama halaman tetap terbuka.');}const data=await res.json();if(!res.ok){if(res.status===401&&user){readCache.invalidate();user=null;csrf='';location.hash='login';}throw Error(data.error||'Request gagal.');}return data;};try{return method==='GET'?await readCache.read(user?.id,path,load):await load();}finally{if(method!=='GET')readCache.invalidate();}}
function bind(id,event,fn){const el=$(id);if(el)el.addEventListener(event,fn);}
function form(id,fn){bind(id,'submit',async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('[type=submit]'),error=e.currentTarget.querySelector('.form-error');btn.disabled=true;if(error)error.textContent='';try{await fn(new FormData(e.currentTarget));}catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{btn.disabled=false;}});}
const empty=(title,copy='')=>`<div class="empty"><strong>${esc(title)}</strong>${esc(copy)}</div>`;
function demoBanner(){if(meta.demo&&meta.source_content)return '<div class="demo"><strong>AKUN UJI</strong> · Materi berasal dari sumber Anda · HSK 3.0 · Riwayat fixture lama tidak berlaku sebagai penentu level.</div>';return meta.demo?'<div class="demo"><strong>LINGKUNGAN DEMO</strong> · Akun, soal dan hasil uji sintetis. Bukan data karyawan atau konten resmi ECB.</div>':'';}
const brand=()=>'<div class="brand"><img src="/logo.png" alt="Logo ECB"><div><strong>ECB</strong><small>LANGUAGE PERFORMANCE SYSTEM</small></div></div>';
function shell(page,title,body){const leader=user.role==='leader',nav=leader?[['overview','Overview','dashboard'],['learning-analytics','Analitik Belajar','learning'],['employees','Employees','employees'],['results','Results','examination'],['ranking','Ranking','ranking']]:[['dashboard','Dashboard','dashboard'],['learning','Learning','learning'],['examination','Examination','examination'],['ranking','Ranking','ranking'],['profile','Profile','profile']];root.innerHTML=`<div class="shell"><aside class="sidebar" id="portal-navigation"><button class="sidebar-close" id="close-menu" type="button" aria-label="Tutup navigasi">×</button>${brand()}<div class="nav-label">${leader?'LEADER PORTAL':'EMPLOYEE PORTAL'}</div><nav aria-label="Navigasi utama">${nav.map(([key,label,ic])=>`<a class="nav-item ${page===key?'active':''}" href="#${key}" ${page===key?'aria-current="page"':''}>${icon(ic)}${label}</a>`).join('')}</nav><div class="sidebar-bottom">${leader?'<p>Akun Leader bersama<br>Seluruh informasi bersifat read-only.</p>':'<p>一步一步，持续进步。<br>Selangkah demi selangkah,<br>terus bertumbuh.</p>'}<button class="nav-item w100" id="logout">${icon('logout')}Keluar</button></div></aside><button class="nav-backdrop" id="nav-backdrop" type="button" aria-label="Tutup navigasi" hidden tabindex="-1"></button><div class="main">${demoBanner()}<header class="topbar"><button class="menu-toggle" id="menu" aria-label="Buka navigasi" aria-controls="portal-navigation" aria-expanded="false">☰</button><div class="breadcrumb">${leader?'Leader':'Employee'} Portal &nbsp; / &nbsp; <span>${esc(title)}</span></div><div class="topbar-actions">${languageSwitcher()}<div class="user">${leader?'<div class="avatar">':'<a class="avatar profile-shortcut" href="#profile/edit" aria-label="Edit profil">'}${esc(user.name.replace('DEMO · ','').slice(0,2).toUpperCase())}${leader?'</div>':'</a>'}<div class="user-copy"><strong>${esc(user.name)}</strong><small>${esc(leader?'Akun bersama · Read-only':user.department)}</small></div></div></div></header><main class="content" id="main-content">${page==='overview'?'<div class="overview-art" aria-hidden="true"></div>':''}${body}<div class="footer-note"><span>ECB Language Performance System</span><span>Waktu Indonesia Tengah · Asia/Makassar</span></div></main></div></div>`;const setMenu=open=>{$('.sidebar').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));$('#nav-backdrop').hidden=!open;if(open)$('#close-menu').focus();else $('#menu').focus();};bind('#menu','click',()=>setMenu(!$('.sidebar').classList.contains('open')));bind('#close-menu','click',()=>setMenu(false));bind('#nav-backdrop','click',()=>setMenu(false));root.onkeydown=e=>{if(e.key==='Escape'&&$('.sidebar')?.classList.contains('open'))setMenu(false);};document.querySelectorAll('.sidebar nav a').forEach(a=>a.addEventListener('click',()=>{if($('.sidebar').classList.contains('open'))setMenu(false);}));bind('#logout','click',async()=>{try{await api('/logout',{method:'POST',body:{}});user=null;csrf='';location.hash='login';}catch(e){toast(e.message);}});}
const heading=(eyebrow,title,copy,extra='',preserveTitle=false)=>`<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 ${preserveTitle?'data-i18n-skip':''}>${esc(title)}</h1><p>${esc(copy)}</p></div>${extra}</div>`;
const stat=(label,value,foot,ic='dashboard')=>`<div class="stat"><div class="stat-top"><span>${esc(label)}</span>${icon(ic)}</div><div class="stat-value">${value}</div><div class="stat-foot">${esc(foot)}</div></div>`;
const memoryLabels={known:'Hafal',review:'Ragu-ragu',unknown:'Belum hafal'};
function readingHTML(text,segments){return segments?segments.map(part=>part.pinyin?`<span class="hanzi-reading" data-i18n-skip><span lang="zh">${esc(part.text)}</span><small class="reading-pinyin">${esc(part.pinyin)}</small></span>`:esc(part.text)).join(''):esc(text);}
function speakButton(text){return /\p{Script=Han}/u.test(String(text||''))?`<button type="button" class="speak-button" data-speak="${encodeURIComponent(text)}" aria-label="Dengarkan pelafalan" aria-pressed="false">🔊 <span>Dengarkan</span></button>`:'';}
function memoryButtons(word){return `<div class="memory-badge">${badge(memoryLabels[word.memory_status]||'Belum ditandai',word.memory_status==='known'?'green':word.memory_status==='review'?'gold':'')}</div><div class="memory-actions" role="group" aria-label="Status hafalan">${Object.entries(memoryLabels).map(([state,label])=>`<button type="button" data-memory="${state}" data-word="${word.id}" class="memory-choice ${state}" aria-pressed="${word.memory_status===state}">${label}</button>`).join('')}</div>`;}
function memorySummary(words){const total=words.length,reviewed=words.filter(w=>w.memory_status).length,known=words.filter(w=>w.memory_status==='known').length,review=words.filter(w=>w.memory_status==='review').length,unknown=words.filter(w=>w.memory_status==='unknown').length,percent=total?Math.round(reviewed/total*100):0,mastery=total?Math.round(known/total*100):0;return `<section class="panel memory-summary"><div class="progress-copy"><strong>Progres pembelajaran</strong><strong>${percent}%</strong></div><div class="progress"><span data-progress="${percent}"></span></div><p class="memory-counts">${reviewed} / ${total} kosakata sudah dipelajari</p><div class="split">${badge(`${known} Hafal`,'green')}${badge(`${review} Ragu-ragu`,'gold')}${badge(`${unknown} Belum hafal`)}</div><p class="muted memory-counts">Penguasaan kosakata: ${mastery}%</p></section>`;}
function packageStatus(p){const labels={mastered:'Semua kosakata hafal',studied:'Sudah dipelajari',in_progress:'Sedang dipelajari',session_completed:'Sesi belajar selesai',not_started:'Belum dipelajari'};return `<div class="package-progress">${badge(labels[p.study_status]||'Belum dipelajari',['mastered','studied'].includes(p.study_status)?'green':p.reviewed_count?'gold':'')}<div class="progress-copy"><span>Progres pembelajaran</span><strong>${p.learning_percent||0}%</strong></div><div class="progress"><span data-progress="${p.learning_percent||0}"></span></div><small>${p.reviewed_count||0} / ${p.word_count} kosakata dipelajari · ${p.mastery_percent||0}% hafal</small></div>`;}
function learningOverview(packages){const total=packages.reduce((n,p)=>n+Number(p.word_count),0),reviewed=packages.reduce((n,p)=>n+Number(p.reviewed_count||0),0),known=packages.reduce((n,p)=>n+Number(p.known_count||0),0),percent=total?Math.round(reviewed/total*100):0;return `<section class="panel learning-overview mb"><div class="panel-head"><h2>Progres pembelajaran</h2>${badge(`${percent}%`,'green')}</div><div class="progress"><span data-progress="${percent}"></span></div><p class="memory-counts">${reviewed} / ${total} kosakata sudah dipelajari</p><p class="muted">${known} kosakata hafal · ${packages.filter(p=>p.study_status==='studied'||p.study_status==='mastered').length} / ${packages.length} paket selesai</p></section>`;}
function latestAttempt(d,track,mode){return d.history.find(r=>r.track===track&&r.mode===mode&&r.status!=='void'&&(mode==='weekly'?r.started_at>=d.weekly.start&&r.started_at<d.weekly.end:true)&&(track!=='hsk'||mode==='placement'||Number(r.level)===Number(d.profile.placement_level||1)));}
function attemptBadge(attempt){if(!attempt)return badge('Belum dikerjakan');if(attempt.status==='submitted'&&attempt.score==null)return badge('Menunggu penilaian','gold');if(attempt.status==='active')return badge('Sedang dikerjakan','gold');return badge(Number(attempt.passed)?'Lulus':'Belum lulus',Number(attempt.passed)?'green':'gold');}
function attemptDetail(attempt){return `<div class="attempt-status">${attemptBadge(attempt)}${attempt&&attempt.status!=='active'?`<span>Nilai: ${num(attempt.score,1)}</span><a href="#exam/${attempt.id}">Lihat hasil →</a>`:''}</div>`;}
function weeklyProgress(d){const completed=Number(!!d.weekly.hsk)+Number(!!d.weekly.work),passed=Number(!!d.weekly.hsk&&!!Number(d.weekly.hsk.passed))+Number(!!d.weekly.work&&!!Number(d.weekly.work.passed));return `<section class="panel mb"><div class="panel-head"><h2>Progres ujian mingguan</h2>${badge(`${completed*50}%`,completed===2?'green':'gold')}</div><div class="progress"><span data-progress="${completed*50}"></span></div><p class="memory-counts">${completed} / 2 ujian selesai · ${passed} / 2 ujian lulus</p><p class="muted">Latihan dan hasil kelulusan ditandai terpisah dari penyelesaian ujian wajib.</p></section>`;}
function wireMemory(words){document.querySelectorAll('[data-memory]').forEach(button=>button.onclick=async()=>{const word=words.find(w=>w.id===button.dataset.word),card=button.closest('[data-vocab]');if(!word||word.memory_status===button.dataset.memory)return;const buttons=card.querySelectorAll('[data-memory]');buttons.forEach(b=>b.disabled=true);try{const saved=await api(`/vocabulary/${word.id}/progress`,{method:'PUT',body:{status:button.dataset.memory}});word.memory_status=saved.status;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.memory===saved.status)));card.querySelector('.memory-badge').innerHTML=badge(memoryLabels[saved.status],saved.status==='known'?'green':saved.status==='review'?'gold':'');$('#memory-summary').innerHTML=memorySummary(words);applyProgress();}catch(error){toast(error.message);}finally{buttons.forEach(b=>b.disabled=false);}});}
function authView(mode='login'){
 root.innerHTML=`${demoBanner()}<div class="auth-page"><div class="auth-story">${brand()}<section><div class="eyebrow">LEARN · PRACTICE · PROGRESS</div><div class="auth-hanzi" lang="zh">共同进步</div><h1>Bahasa membuka<br>lebih banyak<br>kesempatan.</h1><p>Bangun kemampuan Mandarin Anda. Hubungkan pembelajaran dengan pekerjaan, satu langkah setiap hari.</p></section><footer>PT ECB &nbsp; / &nbsp; LANGUAGE PERFORMANCE SYSTEM</footer></div><main class="auth-form"><div class="auth-language">${languageSwitcher()}</div>${mode==='register'?registerHTML():mode==='forgot'?forgotHTML():mode==='recovery'?resetHTML():loginHTML()}</main></div>`;
 if(mode==='login'){
  document.querySelectorAll('[data-portal]').forEach(b=>b.onclick=()=>{loginPortal=b.dataset.portal;authView();});
  form('#login-form',async fd=>{const data=await api('/login',{method:'POST',body:Object.fromEntries(fd)});user=data.user;csrf=data.csrf;location.hash=user.role==='leader'?'overview':'dashboard';});
 }else if(mode==='register')form('#register-form',async fd=>{const b=Object.fromEntries(fd);b.self_level=Number(b.self_level);await api('/register',{method:'POST',body:b});toast('Registrasi berhasil. Username Anda adalah nomor ID.');location.hash='login';});
 else if(mode==='forgot')form('#forgot-form',async fd=>{const r=await api('/forgot',{method:'POST',body:Object.fromEntries(fd)});$('#auth-message').textContent=r.message;});
 else if(mode==='recovery')form('#reset-form',async fd=>{const r=await api('/reset',{method:'POST',body:{password:fd.get('password'),access_token:window.recoveryToken}});window.recoveryToken=null;toast(r.message);location.hash='login';});
}
function loginHTML(){return `<div class="eyebrow mb">SELAMAT DATANG DI<br><span class="login-system-name">ECB LANGUAGE PERFORMANCE SYSTEM</span></div><h2>Mulai langkah Anda.</h2><p>Masuk untuk melanjutkan pembelajaran dan melihat perkembangan.</p><div class="auth-tabs"><button data-portal="employee" class="${loginPortal==='employee'?'selected':''}">Employee Portal</button><button data-portal="leader" class="${loginPortal==='leader'?'selected':''}">Leader Portal</button></div>${loginPortal==='leader'?'<div class="notice">Gunakan akun bersama yang diberikan perusahaan. Portal Leader hanya untuk melihat data.</div>':''}<form id="login-form"><label class="field">${loginPortal==='leader'?'Username Leader':'Nomor ID / Username'}<input name="username" required autocomplete="username" placeholder="${loginPortal==='leader'?'Username perusahaan':'Masukkan nomor ID Anda'}"></label><label class="field">Password<input name="password" type="password" required autocomplete="current-password" placeholder="Masukkan password Anda" maxlength="128"></label><div class="auth-actions"><a href="#forgot">Lupa password?</a></div><div class="form-error" role="alert"></div><button class="btn submit" type="submit">Masuk ke portal &nbsp; →</button></form>${loginPortal==='employee'?'<div class="auth-bottom">Belum punya akun? <a href="#register">Daftar sebagai karyawan</a></div>':''}${meta.demo?'<div class="auth-demo"><strong>Akun uji development</strong><br>Employee: DEMO001 (baru), DEMO002 (sudah placement)<br>Leader: LEADER<br>Password: <strong>DemoMandarin!2026</strong></div>':''}`;}
function registerHTML(){return `<div class="eyebrow mb">EMPLOYEE PORTAL</div><h2>Perjalanan dimulai di sini.</h2><p>Buat akun karyawan. Username otomatis mengikuti nomor ID Anda.</p><form id="register-form" class="form-grid"><label class="field full">Nama lengkap<input name="name" minlength="3" maxlength="100" required autocomplete="name"></label><label class="field">Nomor ID<input name="employee_id" pattern="(?:[A-Za-z0-9]|-){3,30}" required maxlength="30"></label><label class="field">Departemen<select aria-label="Departemen" name="department" required><option value="">Pilih departemen</option>${meta.departments.map(d=>`<option>${esc(d.id)}</option>`).join('')}</select></label><label class="field">Divisi<input name="division" required minlength="2" maxlength="80"></label><label class="field">Jabatan<input name="job_title" required minlength="2" maxlength="80"></label><label class="field full">Email pemulihan<input aria-label="Email pemulihan" name="email" type="email" autocomplete="email" required maxlength="200"><small>Digunakan untuk pemulihan password yang aman.</small></label><label class="field full">Level Mandarin (HSK) menurut Anda<select aria-label="Level self-assessed" name="self_level">${[1,2,3,4,5,6].map(l=>`<option value="${l}">Level ${l}</option>`).join('')}</select><small>Terpisah dari hasil placement internal.</small></label><label class="field full">Buat password<input aria-label="Buat password" name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"><small>Minimal 12 karakter: huruf besar, kecil, angka dan simbol.</small></label><div class="form-error full" role="alert"></div><button class="btn submit full" type="submit">Daftar sebagai karyawan →</button></form><div class="auth-bottom">Sudah punya akun? <a href="#login">Masuk</a></div>`;}
function forgotHTML(){return '<div class="eyebrow mb">PEMULIHAN AKUN</div><h2>Lupa password?</h2><p>Masukkan nomor ID. Petunjuk pemulihan dikirim ke email yang terdaftar bila layanan tersedia.</p><form id="forgot-form"><label class="field">Nomor ID<input name="username" required autocomplete="username"></label><div class="form-error" role="alert"></div><button class="btn submit" type="submit">Kirim petunjuk pemulihan</button></form><p id="auth-message" class="notice mt" role="status">Pada mode lokal, layanan email belum terhubung. Pemulihan oleh IT tersedia melalui CLI.</p><a href="#login">← Kembali masuk</a>';}
function resetHTML(){return '<h2>Buat password baru</h2><form id="reset-form"><label class="field">Password baru<input aria-label="Buat password" name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"><small>Huruf besar, kecil, angka dan simbol.</small></label><div class="form-error" role="alert"></div><button type="submit" class="btn">Simpan password</button></form>';}
function historyHTML(history){if(!history.length)return empty('Belum ada riwayat ujian','Mulai dari placement untuk mengetahui level belajar Anda.');return `<div class="table-wrap"><table><thead><tr><th>UJIAN</th><th>TANGGAL WITA</th><th>NILAI</th><th>STATUS</th><th></th></tr></thead><tbody>${history.map(r=>`<tr><td><strong>${esc(r.track.toUpperCase())}</strong> · ${esc(modeLabel(r.mode))}${r.official?' '+badge('Resmi','green'):''}</td><td>${date(r.started_at,true)}</td><td>${num(r.score,1)}</td><td>${r.status==='active'?badge('Berlangsung','gold'):r.status==='submitted'&&r.score==null?badge('Menunggu penilaian','gold'):r.status==='void'?badge('Invalid','red'):badge(r.passed?'Lulus':'Selesai · belum lulus',r.passed?'green':'gold')}</td><td><a href="#exam/${r.id}">${r.status==='active'?'Lanjutkan':'Pembahasan'} →</a></td></tr>`).join('')}</tbody></table></div>`;}
const modeLabel=m=>({weekly:'Weekly Assessment',placement:'Placement Skill',levelup:'Ujian Naik Level',diagnostic:'Work Diagnostic',random30:'Random 30',random100:'Random 100',grammar:'Grammar Quiz',translation:'Translation Quiz'}[m]||m);
function trend(history){const rows=history.filter(r=>r.official&&r.status==='submitted').slice(0,8).reverse();if(!rows.length)return empty('Tren akan tumbuh bersama Anda','Nilai assessment resmi akan muncul di sini.');return `<svg class="chart" viewBox="0 0 500 170" role="img" aria-label="Tren nilai assessment resmi">${[0,50,100].map(n=>`<text x="0" y="${145-n*1.2}">${n}</text><path d="M30 ${140-n*1.2}H490" stroke="#e4ece8"/>`).join('')}${['hsk','work'].map((track,j)=>{const points=rows.map((r,i)=>({r,x:45+i*425/Math.max(1,rows.length-1),y:140-Number(r.score)*1.2})).filter(p=>p.r.track===track);return `<polyline points="${points.map(p=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="${j?'#b58a35':'#147d79'}" stroke-width="2.5"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="${j?'#b58a35':'#147d79'}"><title>${date(p.r.started_at,true)}: ${p.r.score}</title></circle>`).join('')}`;}).join('')}${rows.map((r,i)=>`<text x="${45+i*425/Math.max(1,rows.length-1)}" y="164" text-anchor="middle">${date(r.started_at,true)}</text>`).join('')}</svg>`;}
async function dashboard(){const viewVersion=routeVersion;const d=await api('/dashboard');if(viewVersion!==routeVersion)return;user=d.profile;const w=d.weekly,completed=Number(!!w.hsk)+Number(!!w.work),level=user.placement_level;const mission=(track,label,copy)=>{const result=w[track];return `<div class="mission"><div class="mission-icon">${track==='hsk'?'文':'工'}</div><div class="mission-body"><strong>${label}</strong><p>${esc(copy)} · ${result?`Nilai ${num(result.score)}`:'30 soal · 25 menit'}</p></div>${result?badge(result.passed?'Lulus':'Selesai',result.passed?'green':'gold'):`<button class="btn secondary" data-start="weekly" data-track="${track}">Mulai →</button>`}</div>`;};
 if(viewVersion!==routeVersion)return;shell('dashboard','Dashboard',heading('YOUR LEARNING JOURNEY',`Selamat datang, ${user.name.replace('DEMO · ','').split(' ')[0]}.`,'Langkah kecil hari ini, kemampuan yang lebih baik esok hari.',`<div class="date-chip">${date(Date.now()/1000)} · WITA</div>`)+`<section class="hero"><div><span class="eyebrow">${level?'TERUSKAN PERKEMBANGAN ANDA':'LANGKAH PERTAMA'}</span><h2>${level?`Anda belajar di HSK ${level}.`:'Kenali kemampuan Mandarin Anda.'}</h2><p>${level?'Luangkan waktu untuk belajar, lalu tuntaskan dua assessment wajib minggu ini.':'Selesaikan placement adaptif untuk menentukan level belajar. Hasil ini merupakan evaluasi internal, bukan sertifikasi HSK resmi.'}</p>${level?'<div class="dashboard-actions"><a class="btn" href="#learning">Lanjutkan belajar &nbsp; →</a><a class="btn secondary" href="#levelup">Ujian Naik Level →</a></div>':'<button class="btn" data-start="placement" data-track="hsk">Mulai / lanjutkan placement →</button>'}</div></section><div class="stats">${stat('Level belajar',level?`HSK ${level}`:'Belum ada',`Self-assessed: Level ${user.self_level}`,'learning')}${stat('Assessment minggu ini',`${completed}<small> / 2 selesai</small>`,'HSK + Work Vocabulary','examination')}${stat('Waktu belajar aktif',`${num(w.minutes)}<small> / 60 menit</small>`,'Target belajar mingguan','clock')}${stat('Baseline Work',num(user.baseline_work,1),user.baseline_work==null?'Selesaikan diagnostic kerja':'Terpisah dari baseline HSK','ranking')}</div><div class="grid2"><section class="panel"><div class="panel-head"><h2>Misi minggu ini</h2>${badge('Minggu berjalan','green')}</div>${mission('hsk','HSK Weekly Assessment',level?`Sesuai level HSK ${level}`:'Placement diperlukan')}${mission('work','Work Weekly Assessment','18 umum + 12 departemen')}<div class="progress-copy"><span>Belajar aktif</span><strong>${num(w.minutes)} / 60 menit</strong></div><div class="progress"><span data-progress="${Math.min(100,w.minutes/60*100)}"></span></div><p class="weekly-note">${date(w.start,true)} – ${date(w.end-1,true)} · Tenggat Minggu 23.59 WITA.<br>Selesai dan lulus merupakan status yang berbeda.</p></section><section class="panel"><div class="panel-head"><h2>Perkembangan nilai</h2><small>Assessment resmi</small></div><div class="legend"><span><i></i>HSK</span><span><i class="gold"></i>Work</span></div>${trend(d.history)}</section></div><section class="panel mb"><div class="panel-head"><h2>Riwayat ujian</h2><a href="#examination">Semua jenis ujian →</a></div>${historyHTML(d.history.slice(0,8))}</section><div class="grid2"><section class="panel"><div class="panel-head"><h2>Pengingat Anda</h2><small>In-app</small></div>${d.notifications.length?d.notifications.map(n=>`<div class="notification ${n.read_at?'read':''}"><div>${esc(n.message)}<br><small>${date(n.created_at,true)}</small></div>${n.read_at?'':`<button data-read="${n.id}">Tandai dibaca</button>`}</div>`).join(''):empty('Anda sudah mengetahui langkah berikutnya','Pengingat progres tersedia pada Senin, Kamis, Sabtu dan Minggu.')}</section><section class="panel"><div class="panel-head"><h2>Rekomendasi berikutnya</h2></div><p class="muted">${level?`Pelajari paket HSK ${level} dan kosakata kerja departemen ${esc(user.department)} sebelum assessment.`:'Mulai dengan placement untuk membuka assessment HSK sesuai level Anda.'}</p>${user.baseline_work==null?'<button class="btn secondary" data-start="diagnostic" data-track="work">Mulai Work Diagnostic →</button>':'<a class="btn secondary" href="#learning">Buka materi belajar →</a>'}</section></div>`);applyProgress();wireStarts();document.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{try{await api(`/notifications/${b.dataset.read}/read`,{method:'POST',body:{}});await dashboard();}catch(e){toast(e.message);}});}
function applyProgress(){document.querySelectorAll('[data-progress]').forEach(el=>{el.style.width=Math.max(0,Math.min(100,Number(el.dataset.progress)))+'%';});}
function wireStarts(){document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const q=await api('/exams',{method:'POST',body:{mode:b.dataset.start,track:b.dataset.track}});location.hash='exam/'+q.id;}catch(e){toast(e.message);b.disabled=false;}});}
async function playPage(mode,arg){const viewVersion=routeVersion;const {mountLearningPlay}=await import('./learning-play.js');if(viewVersion!==routeVersion)return;await mountLearningPlay({api,shell,esc,root,toast,user,packages:()=>api('/packages'),cleanup:fn=>{cleanup=fn;}},mode,arg);}
async function learning(mode='center',arg=''){const viewVersion=routeVersion;const {mountLearningCenter}=await import('./learning-center.js');if(viewVersion!==routeVersion)return;await mountLearningCenter({api,shell,esc,root,toast,user,packages:()=>api('/packages'),cleanup:fn=>{cleanup=fn;}},mode,arg);}
async function learningLegacy(){
 const packages=await api('/packages');let track='hsk',level=user.placement_level||1;
 function render(){const filtered=packages.filter(p=>p.track===track&&(track!=='hsk'||p.level===level));
 shell('learning','Learning',heading('KNOWLEDGE, ONE STEP AT A TIME','Ruang belajar Anda.','HSK 3.0 level 1–6 dan kosakata yang dekat dengan pekerjaan.','<a class="btn secondary" href="#library">Perpustakaan sumber →</a>')+`
 <div class="notice">${meta.source_content?'Pelajari kosakata dan materi HSK 3.0 sesuai level Anda. Evaluasi ini internal, bukan sertifikasi HSK.':meta.demo?'Fixture hanya untuk pengujian perangkat lunak.':'Materi published belum tersedia.'}</div>
 <form class="filters" id="learning-filter"><label>Jalur<select name="track"><option value="hsk" ${track==='hsk'?'selected':''}>HSK 3.0</option><option value="work" ${track==='work'?'selected':''}>Work Vocabulary</option></select></label><label>Level HSK<select name="level">${[1,2,3,4,5,6].map(l=>`<option ${l===level?'selected':''}>${l}</option>`).join('')}</select></label><button type="submit" class="btn secondary">Tampilkan</button></form>
 ${learningOverview(filtered)}<div class="package-grid">${filtered.map(p=>`<article class="panel package"><div class="package-code">${p.track==='hsk'?'文':'工'}</div><div class="section-tag">${p.track==='hsk'?`HSK 3.0 / LEVEL ${p.level}`:'WORK VOCABULARY'}</div><h3>${esc(p.title)}</h3><p>${p.word_count?`${p.word_count} kosakata ${meta.source_content?'dari sumber':meta.demo?'DEMO':''} · ${p.lesson_count||0} materi`:'Menunggu konten yang disetujui'}</p>${packageStatus(p)}<a class="btn secondary" href="#package/${p.id}">${p.reviewed_count?'Pelajari kembali':'Buka paket'} →</a></article>`).join('')}</div>`);
 applyProgress();form('#learning-filter',async fd=>{track=fd.get('track');level=Number(fd.get('level'));render();});
 }render();
}

async function packagePage(pid){const viewVersion=routeVersion;const p=await api('/packages/'+pid);let session=null,activeSeconds=0,lastInteraction=Date.now(),pending=false;function render(){if(viewVersion!==routeVersion)return;shell('learning','Learning',heading(p.track==='hsk'?`HSK ${p.level}`:'WORK VOCABULARY',p.title,'Baca Hanzi, ucapkan Pinyin, dan pahami maknanya.')+`<a href="#learning">← Kembali ke paket</a>${meta.source_content?'<div class="notice mt">Materi sumber HSK 3.0 dan kosakata kerja. Soal menggunakan kosakata, konteks, dan grammar sesuai level sumber.</div>':meta.demo?'<div class="notice mt">Fixture khusus pengujian.</div>':''}${(p.words.length||p.lessons?.length)?`<div class="learning-bar"><span><span class="active-pill"></span>Waktu aktif sesi: <strong id="learning-time">00:00</strong><br><small id="learning-status">Mulai sesi untuk mencatat waktu belajar aktif.</small></span><div class="split">${speechSettings()}<button class="btn" id="start-learning">Mulai sesi belajar</button><button class="btn secondary" id="finish-learning" disabled>Selesaikan sesi</button></div></div><div id="memory-summary">${p.words.length?memorySummary(p.words):''}</div><div class="word-grid">${p.words.map(w=>`<article class="panel word" data-vocab="${w.id}"><div class="hanzi" lang="zh">${esc(w.hanzi)}</div>${speakButton(w.hanzi)}<div class="pinyin">${esc(w.pinyin)}</div><div class="meaning">${esc(w.meaning)}</div>${meta.source_content?sourceRef(w.source_ref):''}${meta.source_content&&w.examples?wordExamples(w.examples):''}${memoryButtons(w)}</article>`).join('')}</div>${(p.lessons||[]).length?'<section class="mt"><h2>Grammar, contoh & bacaan sumber</h2>'+p.lessons.map(lessonHTML).join('')+'</section>':''}<p class="weekly-note">Waktu divalidasi server: heartbeat 15 detik, idle 60 detik, maksimal sesi 30 menit. Sesi yang selesai minimal 15 detik dapat menandai progres paket.</p>`:empty('Materi sedang ditinjau','Konten draft dan under review belum dapat dipelajari sebagai materi resmi.')}`);bind('#start-learning','click',async()=>{try{session=await api('/learning/start',{method:'POST',body:{package_id:pid}});lastInteraction=Date.now();$('#start-learning').disabled=true;$('#finish-learning').disabled=false;$('#learning-status').textContent='Sesi aktif. Interaksi diperlukan agar waktu terus dihitung.';}catch(e){toast(e.message);}});bind('#finish-learning','click',async()=>{if(!session)return;try{const r=await beat(true);session=null;toast(r.completed?'Progres paket tersimpan.':'Sesi tersimpan; belajar aktif minimal 15 detik untuk menyelesaikan paket.');$('#finish-learning').disabled=true;$('#start-learning').disabled=false;}catch(e){toast(e.message);}});}
 async function beat(complete=false){if(pending)return {};pending=true;try{const r=await api(`/learning/${session.id}/heartbeat`,{method:'POST',body:{active:document.visibilityState==='visible'&&Date.now()-lastInteraction<60000,complete}});activeSeconds=r.active_seconds;$('#learning-time').textContent=fmtTime(activeSeconds);$('#learning-status').textContent=r.closed?'Sesi ditutup.':'Waktu aktif tervalidasi server.';if(r.closed)session=null;return r;}finally{pending=false;}}
 const activity=()=>{lastInteraction=Date.now();};['pointerdown','keydown','scroll','touchstart'].forEach(e=>document.addEventListener(e,activity,{passive:true}));render();applyProgress();wireMemory(p.words);document.querySelectorAll('.lesson-body p').forEach(line=>{if(/\p{Script=Han}/u.test(line.textContent))line.insertAdjacentHTML('afterend',speakButton(line.textContent));});const disposeSpeech=wireSpeech(root,{notify:toast});const timer=setInterval(()=>{if(session)beat().catch(e=>{if($('#learning-status'))$('#learning-status').textContent=e.message;});},15000);cleanup=()=>{disposeSpeech();clearInterval(timer);['pointerdown','keydown','scroll','touchstart'].forEach(e=>document.removeEventListener(e,activity));};}
async function examination(){const viewVersion=routeVersion;
 const d=await api('/dashboard');if(viewVersion!==routeVersion)return;user=d.profile;
 if(viewVersion!==routeVersion)return;shell('examination','Examination',heading('TURN KNOWLEDGE INTO PROGRESS','Uji kemampuan Anda.','Dua assessment wajib setiap minggu. Latihan tersedia tanpa batas.')+`
 <div class="notice">Weekly Assessment: hasil valid pertama menjadi nilai resmi. Latihan tidak memengaruhi ranking. Jawaban dan pembahasan dibuka setelah submit.</div>${weeklyProgress(d)}
 <div class="grid2">${['hsk','work'].map(track=>{const weekly=latestAttempt(d,track,'weekly'),placement=latestAttempt(d,track,track==='hsk'?'placement':'diagnostic');return `<section class="panel"><div class="panel-head"><h2>${track==='hsk'?'HSK 3.0':'Work Vocabulary'}</h2>${badge(track==='hsk'?user.placement_level?`Level ${user.placement_level}`:'Perlu placement':user.department,'green')}</div><p class="muted">${track==='hsk'?'Sesuai level hasil placement internal.':'Komposisi 60% umum dan 40% departemen.'}</p>
 <div class="mission"><div class="mission-body"><strong>Weekly Assessment</strong><p>30 soal · 25 menit · Lulus ≥ 80</p>${attemptDetail(weekly)}</div>${weekly&&weekly.status!=='active'?'':`<button class="btn" data-start="weekly" data-track="${track}">${weekly?'Lanjutkan':'Mulai'} →</button>`}</div>
 ${['random30','random100','grammar','translation'].map(mode=>{const last=latestAttempt(d,track,mode);return `<div class="mission"><div class="mission-body"><strong>${modeLabel(mode)}</strong><p>Latihan · ${mode==='random100'?'100':mode==='random30'?'30':'10'} soal${mode==='translation'?' · Dua arah':''}</p>${attemptDetail(last)}</div><button class="btn secondary" data-start="${mode}" data-track="${track}">${last?.status==='active'?'Lanjutkan':last?'Latihan lagi':'Latihan'} →</button></div>`;}).join('')}
 ${track==='work'?'<div class="mt"><strong>Work Diagnostic</strong>'+attemptDetail(placement)+(user.baseline_work==null?'<button class="btn secondary mt" data-start="diagnostic" data-track="work">Work Diagnostic →</button>':'')+'</div>':''}</section>`;}).join('')}</div>
 <section class="panel"><div class="panel-head"><h2>Seluruh riwayat ujian</h2></div>${historyHTML(d.history)}</section>`);
 applyProgress();wireStarts();if(meta.source_content){const status=await api('/content-status');if(!status.department_ready){document.querySelectorAll('[data-track=work]').forEach(b=>{b.disabled=true;b.title='Materi departemen belum dapat dibaca';});document.querySelector('.content').insertAdjacentHTML('afterbegin','<div class="notice error">Assessment Work departemen '+esc(user.department)+' belum tersedia karena sumber departemen belum dapat dibaca. Materi umum tetap tersedia di Learning dan Perpustakaan Sumber.</div>');}}
}

async function levelUpPage(){const viewVersion=routeVersion;
 const d=await api('/dashboard');if(viewVersion!==routeVersion)return;user=d.profile;const catalog=await api('/official-hsk'),level=Number(user.placement_level||0),target=Math.min(6,level+1),paper=catalog.find(p=>p.level===target),attempt=d.history.find(r=>r.mode==='levelup'&&r.status!=='void');
 if(viewVersion!==routeVersion)return;shell('dashboard','Ujian Naik Level',heading('SIMULASI HSK · ARSIP RESMI','Ujian Naik Level','Paket asli PDF dan audio dari SOAL HSK LENGKAP; bukan kuis kosakata singkat.')+`<section class="panel"><h2>Level belajar Anda: ${level?'HSK '+level:'Belum ditetapkan'}</h2><p>Ujian memakai listening, reading dan writing sesuai paket sumber. Durasi mencakup 5 menit persiapan serta waktu pemindahan jawaban listening. Angka durasi bersifat perkiraan; listening mengikuti panjang MP3 asli.</p>${!level?'<div class="notice">Selesaikan Placement Skill satu kali terlebih dahulu.</div><button class="btn mt" data-start="placement" data-track="hsk">Mulai / lanjut placement →</button>':`<form id="official-start"><label class="field">Level simulasi<select name="level">${catalog.filter(p=>p.level<=target).map(p=>`<option value="${p.level}" ${p.level===target?'selected':''}>HSK ${p.level} · ${p.total} soal · ${p.minutes} menit</option>`).join('')}</select></label><button type="submit" class="btn">Mulai / lanjut simulasi HSK →</button><div class="form-error" role="alert"></div></form>`}<div class="notice mt">Format mengikuti arsip HSK yang Anda berikan. Ini simulasi internal, bukan sertifikasi atau ujian HSK 3.0 terbaru. Kenaikan level internal tetap mensyaratkan nilai minimal 80%; skor simulasi tidak terkalibrasi sebagai skor resmi.</div>${!paper?.ai_ready?'<p class="muted mt">AI untuk penilaian jawaban tulis belum dikonfigurasi. Jawaban yang perlu AI akan disimpan sebagai menunggu penilaian; level tidak dinaikkan sebelum nilai lengkap.</p>':''}${attempt?'<div class="mt">'+attemptDetail(attempt)+'</div>':''}</section><section class="panel mt"><h2>Struktur paket HSK</h2><div class="table-wrap"><table><thead><tr><th>LEVEL</th><th>LISTENING</th><th>READING</th><th>WRITING</th><th>TOTAL</th><th>MENIT</th></tr></thead><tbody>${catalog.map(p=>`<tr><td>HSK ${p.level}</td><td>${p.counts.listening}</td><td>${p.counts.reading}</td><td>${p.counts.writing}</td><td>${p.total}</td><td>${p.minutes}</td></tr>`).join('')}</tbody></table></div></section><section class="panel mt"><h2>Riwayat ujian naik level</h2>${historyHTML(d.history.filter(r=>r.mode==='levelup'))}</section>`);wireStarts();form('#official-start',async fd=>{const q=await api('/exams',{method:'POST',body:{mode:'levelup',track:'hsk',level:Number(fd.get('level'))}});location.hash='exam/'+q.id;});
}
async function examPage(sid){const viewVersion=routeVersion;const official=await api('/exams/'+sid);if(official.format==='official_archive'){await mountOfficialExam(official,{api,shell,heading,esc,fmtTime,toast,readOnly:user.role==='leader',setCleanup:fn=>{cleanup=fn;}});return;}let q=official,index=0,answers={...q.answers},dirty={},saving=false,disposed=false,remaining=Math.max(0,q.deadline-q.server_now),syncBase=Date.now();
 if(q.result){await resultPage(q,true);return;}
 function render(){const item=q.questions[index];if(viewVersion!==routeVersion)return;shell('examination','Ujian berlangsung',heading(q.mode==='weekly'?'WEEKLY ASSESSMENT':'INTERNAL ASSESSMENT',`${q.track.toUpperCase()} · ${modeLabel(q.mode)}`,`Level ${q.level} · ${q.questions.length} soal · ${q.assessment?.content_mode==='source'?'HSK 3.0 · materi sumber · ':meta.demo?'DEMO · ':''}Satu jawaban benar per soal`)+`<div class="quiz-layout"><section class="panel"><span class="eyebrow">SOAL ${index+1} DARI ${q.questions.length}</span><h2 class="quiz-question">${readingHTML(item.prompt,item.prompt_reading)}</h2><fieldset class="quiz-options"><legend class="sr-only">Pilih jawaban</legend>${item.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${o.id}" ${answers[item.id]===o.id?'checked':''}><span>${String.fromCharCode(65+i)}.</span><span class="option-reading">${readingHTML(o.label,o.reading)}</span></label>`).join('')}</fieldset><div class="quiz-controls"><button class="btn secondary" id="previous" ${index===0?'disabled':''}>← Sebelumnya</button><button class="btn secondary" id="next" ${index===q.questions.length-1?'disabled':''}>Selanjutnya →</button></div><p class="weekly-note" id="save-status" aria-live="polite">${Object.keys(dirty).length?'Menyimpan jawaban…':'Jawaban tersimpan di server.'}</p></section><aside class="panel quiz-side"><span class="eyebrow">SISA WAKTU</span><div class="timer" id="exam-timer">${fmtTime(remaining-Math.floor((Date.now()-syncBase)/1000))}</div><p>Waktu server berlaku. Saat habis, jawaban tersimpan disubmit otomatis.</p><div class="question-grid">${q.questions.map((r,i)=>`<button class="${answers[r.id]?'answered':''} ${i===index?'current':''}" data-question="${i}" aria-label="Buka soal ${i+1}">${i+1}</button>`).join('')}</div><div class="progress-copy"><span>Progres jawaban</span><strong id="answer-percent">${Math.round(Object.keys(answers).length/q.questions.length*100)}%</strong></div><div class="progress"><span id="exam-answer-progress" data-progress="${Object.keys(answers).length/q.questions.length*100}"></span></div><p id="answer-count">${Object.keys(answers).length} / ${q.questions.length} terjawab</p><button class="btn" id="submit-exam">Selesaikan & kirim →</button><p id="submit-hint">Periksa jawaban sebelum mengirim.</p></aside></div>`);applyProgress();$('.quiz-options').style.border='0';$('.quiz-options').style.padding='0';
 document.querySelectorAll('[name=answer]').forEach(r=>r.onchange=()=>{answers[item.id]=r.value;dirty[item.id]=r.value;$('#save-status').textContent='Menyimpan jawaban…';const grid=document.querySelector(`[data-question="${index}"]`);grid.classList.add('answered');$('#answer-count').textContent=`${Object.keys(answers).length} / ${q.questions.length} terjawab`;$('#answer-percent').textContent=Math.round(Object.keys(answers).length/q.questions.length*100)+'%';$('#exam-answer-progress').style.width=Object.keys(answers).length/q.questions.length*100+'%';flush();});bind('#previous','click',()=>{index--;render();});bind('#next','click',()=>{index++;render();});document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{index=Number(b.dataset.question);render();});bind('#submit-exam','click',submit);
 }
 async function flush(){if(saving||!Object.keys(dirty).length||disposed)return;saving=true;const batch={...dirty};try{const r=await api(`/exams/${sid}/answers`,{method:'PUT',body:{answers:batch}});if(disposed)return;if(r.result){disposed=true;cleanup();await resultPage(r,true);return;}for(const [key,value]of Object.entries(batch))if(dirty[key]===value)delete dirty[key];if($('#save-status'))$('#save-status').textContent=Object.keys(dirty).length?'Menyimpan jawaban…':'Jawaban tersimpan di server.';}catch(e){if($('#save-status'))$('#save-status').textContent=e.message;}finally{saving=false;}}
 async function submit(){const b=$('#submit-exam');if(b)b.disabled=true;try{q=await api(`/exams/${sid}/submit`,{method:'POST',body:{answers}});disposed=true;cleanup();await resultPage(q,true);}catch(e){toast(e.message);if(b)b.disabled=false;}}
 render();const interval=setInterval(()=>{if(disposed)return;const left=remaining-Math.floor((Date.now()-syncBase)/1000);if($('#exam-timer'))$('#exam-timer').textContent=fmtTime(left);if(left<=0)submit();else flush();},1000);cleanup=()=>{disposed=true;clearInterval(interval);};
}
async function resultPage(q,autoAdvance=false){const me=await api('/me');user=me.user;const next=user.role==='employee'&&q.continuation;if(next&&autoAdvance){try{const following=await api('/exams',{method:'POST',body:{track:'hsk',mode:next.mode}});toast(`Lulus HSK ${q.level}. Melanjutkan ke HSK ${following.level}.`);location.hash='exam/'+following.id;return;}catch(error){toast(error.message);}}const questions=q.questions;shell(user.role==='leader'?'results':'examination','Hasil ujian',heading('REFLECT, THEN MOVE FORWARD','Setiap hasil adalah langkah maju.',`${q.track.toUpperCase()} · ${modeLabel(q.mode)} · ${date(q.submitted_at||q.started_at)}`)+`${q.status==='void'?'<div class="notice error">Arsip hasil lama/fixture. Nilai ini tidak digunakan untuk placement atau ranking HSK 3.0. Mulai placement baru dari Dashboard.</div>':''}<section class="panel mb"><div class="grid2"><div><div class="eyebrow">NILAI ANDA ${q.official?'· RESMI':'· NON-RANKING'}</div><div class="result-score">${num(q.result.score,1)}<small> /100</small></div>${badge(q.result.passed?'Lulus':'Selesai · belum lulus',q.result.passed?'green':'gold')}<p class="muted mt">Ambang kelulusan 80. ${q.official?'Hasil valid pertama tersimpan sebagai nilai resmi.':'Hasil ini tidak menimpa nilai resmi mingguan.'}</p></div><div><h2>Langkah berikutnya</h2><p class="muted">${next?'Anda melewati ambang tahap ini. Ujian level berikutnya akan terbuka otomatis.':q.mode==='levelup'?`Ujian naik level selesai. Level belajar Anda: HSK ${user.placement_level}.`:q.mode==='placement'?`Placement internal selesai. Level belajar Anda: HSK ${user.placement_level}.`:'Pelajari kembali materi yang belum dipahami, lalu gunakan latihan untuk memperkuat kemampuan.'}</p>${next?'<button class="btn" data-start="'+next.mode+'" data-track="hsk">Lanjutkan ke level berikutnya →</button>':user.role==='employee'?'<a class="btn" href="#learning">Kembali belajar →</a>':'<a class="btn" href="#results">Kembali ke hasil →</a>'}</div></div></section><section class="panel"><div class="panel-head"><h2>Pembahasan lengkap</h2><small>Snapshot konten saat sesi dimulai</small></div>${questions.length?questions.map((r,i)=>`<article class="review"><h3>${i+1}. ${readingHTML(r.prompt,r.prompt_reading)}</h3><ul>${r.options.map(o=>`<li class="${o.id===r.correct_id?'correct':o.id===r.selected?'wrong':''}"><span data-i18n-skip>${readingHTML(o.label,o.reading)}</span> ${o.id===r.correct_id?'<span>✓ Jawaban benar</span>':''}${o.id===r.selected?'<span> · Pilihan Anda</span>':''}</li>`).join('')}</ul>${r.selected?'':'<p>Tidak dijawab.</p>'}<p data-i18n-skip>${esc(r.explanation)}</p>${sourceRef(r.source_ref)}</article>`).join(''):empty('Riwayat sintetis DEMO','Fixture ringkasan historis tidak memuat snapshot soal. Ujian baru selalu menyimpan snapshot lengkap.')}</section>`);wireStarts();}
async function ranking(mode=''){const version=routeVersion;if(mode==='official'){await officialRanking();if(version!==routeVersion)return;const h=document.querySelector('.content');if(h)h.insertAdjacentHTML('afterbegin','<a class="lc-back" href="#ranking">← Panggung Prestasi ECB</a>');return;}const {mountAchievements}=await import('./achievements.js');if(version!==routeVersion)return;await mountAchievements({api,shell,esc,root,user,cleanup:fn=>{cleanup=fn;}});}
async function officialRanking(){const viewVersion=routeVersion;let period='monthly',track='',level=user.placement_level||1,at='';async function render(){let query=`period=${period}`;if(track)query+=`&track=${track}&level=${level}`;if(at)query+=`&at=${Math.floor(new Date(at+'T12:00:00+08:00').getTime()/1000)}`;const d=await api('/rankings?'+query);if(viewVersion!==routeVersion)return;shell('ranking','Ranking',heading('GROW TOGETHER','Perkembangan layak diapresiasi.','Ranking perusahaan berdasarkan assessment resmi dan konsistensi belajar.')+`<form class="filters" id="ranking-filter"><label>Periode<select name="period">${[['weekly','Mingguan'],['monthly','Bulanan'],['quarterly','Triwulan'],['semester','Semester'],['yearly','Tahunan']].map(([v,l])=>`<option value="${v}" ${period===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Tanggal acuan<input name="at" type="date" value="${at}"></label><label>Kategori<select name="track"><option value="">Overall</option><option value="hsk" ${track==='hsk'?'selected':''}>HSK</option><option value="work" ${track==='work'?'selected':''}>Work</option></select></label><label>Level kategori<select name="level">${[1,2,3,4,5,6].map(l=>`<option ${l===Number(level)?'selected':''}>${l}</option>`).join('')}</select></label><button type="submit" class="btn secondary">Terapkan</button></form><div class="notice">${date(d.period.start,true)} – ${date(d.period.end-1,true)} · ${d.provisional?'Periode berjalan, hasil sementara. Minggu yang belum berakhir tidak dihitung gagal.':'Snapshot historis dengan formula '+esc(d.policy)+'.'} Data baseline/benchmark yang belum cukup diberi label insufficient_data.</div><section class="panel"><div class="panel-head"><h2>${track?'Ranking kategori · '+track.toUpperCase()+' · Level '+level:'Ranking keseluruhan'}</h2>${badge(d.provisional?'Sementara':'Snapshot','green')}</div><div class="table-wrap"><table><thead><tr><th>PERINGKAT</th><th>KARYAWAN</th><th>DEPARTEMEN</th><th>LEVEL</th><th>${track?'NILAI KATEGORI':'OVERALL'}</th><th>HSK</th><th>WORK</th><th>IMPROVEMENT</th><th>COMPLETION</th><th>KONSISTENSI</th><th>STATUS</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${num(track?r.category_rank:r.rank)}</td><td><strong data-i18n-skip>${esc(r.name)}</strong></td><td>${esc(r.department)}</td><td>${r.level?'HSK '+r.level:'—'}</td><td><strong>${num(track?r.category_score:r.score,2)}</strong></td><td>${num(r.hsk,1)}</td><td>${num(r.work,1)}</td><td>${num(r.improvement,1)}</td><td>${num(r.completion,1)}${r.completion==null?'':'%'}</td><td>${num(r.consistency,1)}${r.consistency==null?'':'%'}</td><td>${badge(r.status,r.eligible?'green':'gold')}</td></tr>`).join('')}</tbody></table></div>${!d.rows.length?empty('Belum ada peserta dalam kategori ini'):''}<p class="rank-formula mt">Bobot: HSK 25% · Work 25% · Improvement 30% (HSK 15% + Work 15%) · Completion 10% · Konsistensi 10%.<br>Juara umum memerlukan completion dan konsistensi ≥ 80%, baseline serta data resmi yang cukup, tanpa sesi invalid. Practice tidak dihitung. Improvement menggunakan benchmark terkalibrasi yang sama.<br>Tie-breaker: improvement, nilai resmi terbaru, completion; nilai tetap sama berarti seri.</p></section><section class="panel mt"><h2>Penghargaan periode ini</h2>${[['Overall Champion',d.awards.overall_champion],['Best Performance',d.awards.best_performance],['Most Improved',d.awards.most_improved]].map(([label,ids])=>`<div class="mission"><strong class="mission-body">${label}</strong><span>${ids.length?ids.map(i=>esc(d.rows.find(r=>r.id===i)?.name||'Peserta eligible')).join(', '):'Belum ada peserta eligible'}</span></div>`).join('')}</section>`);form('#ranking-filter',async fd=>{period=fd.get('period');track=fd.get('track');level=Number(fd.get('level'));at=fd.get('at');await render();});}await render();}
