async function leaderPage(page){const viewVersion=routeVersion;let filters={};async function render(){const params=new URLSearchParams(Object.entries(filters).filter(([,v])=>v)),d=await api('/leader?'+params);const employees=d.employees;const distinct=k=>[...new Set(employees.map(e=>e[k]))];if(viewVersion!==routeVersion)return;shell(page,{overview:'Overview',employees:'Employees',results:'Results'}[page],heading('COMPANY LEARNING INTELLIGENCE',page==='overview'?'Gambaran pembelajaran perusahaan.':page==='employees'?'Perkembangan setiap karyawan.':'Hasil yang dapat ditelusuri.','Leader Portal · Akun bersama · Seluruh informasi bersifat read-only.')+`<form class="filters" id="leader-filter"><label>Cari nama<input name="q" placeholder="Nama karyawan" value="${esc(filters.q||'')}"></label><label>Departemen<select name="department"><option value="">Semua departemen</option>${meta.departments.map(d=>`<option ${filters.department===d.id?'selected':''}>${esc(d.id)}</option>`).join('')}</select></label>${[['division','Divisi'],['job_title','Jabatan']].map(([k,l])=>`<label>${l}<input name="${k}" value="${esc(filters[k]||'')}" placeholder="Semua ${l.toLowerCase()}" list="${k}-list"><datalist id="${k}-list">${distinct(k).map(v=>`<option value="${esc(v)}">`).join('')}</datalist></label>`).join('')}<label>Level<select name="level"><option value="">Semua level</option>${[1,2,3,4,5,6].map(l=>`<option ${Number(filters.level)===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Periode<select name="period">${[['weekly','Mingguan'],['monthly','Bulanan'],['quarterly','Triwulan'],['semester','Semester'],['yearly','Tahunan']].map(([v,l])=>`<option value="${v}" ${(filters.period||'weekly')===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="btn secondary" type="submit">Terapkan filter</button></form><div class="stats">${stat('Total karyawan',num(d.kpi.total),`${d.kpi.active_learners} aktif belajar pada periode`,'employees')}${stat('Weekly completion',`${num(d.kpi.weekly_completion,1)}<small>%</small>`,'Dua assessment wajib / karyawan','examination')}${stat('Rata-rata HSK',num(d.kpi.hsk,1),'Assessment resmi dalam periode','learning')}${stat('Rata-rata Work',num(d.kpi.work,1),`Pass rate: ${num(d.kpi.pass_rate,1)}${d.kpi.pass_rate==null?'':'%'}`,'ranking')}</div>${page==='overview'?`<div class="grid2"><section class="panel"><div class="panel-head"><h2>Perbandingan departemen</h2><small>Rata-rata nilai resmi</small></div>${d.departments.map(x=>`<div class="bar-row"><span>${esc(x.department)}</span><div class="progress"><span data-progress="${x.average||0}"></span></div><strong>${num(x.average,1)}</strong></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Distribusi level</h2><small>Hasil placement</small></div>${d.levels.map(x=>`<div class="bar-row"><span>HSK ${x.level}</span><div class="progress"><span data-progress="${d.kpi.total?x.count/d.kpi.total*100:0}"></span></div><strong>${x.count}</strong></div>`).join('')}<small>Belum placement: ${employees.filter(e=>!e.placement_level).length}</small></section></div>`:''}<section class="panel"><div class="panel-head"><h2>${page==='results'?'Hasil assessment resmi':'Karyawan & misi mingguan'}</h2><button id="export" class="btn secondary">Ekspor CSV</button></div>${page==='results'?`<div class="table-wrap"><table><thead><tr><th>KARYAWAN</th><th>DEPARTEMEN</th><th>UJIAN</th><th>TANGGAL</th><th>NILAI</th><th>STATUS</th><th></th></tr></thead><tbody>${employees.flatMap(e=>e.results.map(r=>`<tr><td data-i18n-skip>${esc(e.name)}</td><td>${esc(e.department)}</td><td>${r.track.toUpperCase()} · HSK ${r.level}</td><td>${date(r.started_at,true)}</td><td>${num(r.score,1)}</td><td>${badge(r.passed?'Lulus':'Selesai · belum lulus',r.passed?'green':'gold')}</td><td><a href="#exam/${r.id}">Lihat hasil →</a></td></tr>`)).join('')}</tbody></table></div>${employees.some(e=>e.results.length)?'':empty('Belum ada hasil resmi pada periode terpilih')}`:`<div class="table-wrap"><table><thead><tr><th>KARYAWAN</th><th>DEPARTEMEN</th><th>DIVISI / JABATAN</th><th>LEVEL</th><th>HSK MINGGU INI</th><th>WORK MINGGU INI</th><th>BELAJAR AKTIF</th><th></th></tr></thead><tbody>${employees.map(e=>`<tr><td><strong data-i18n-skip>${esc(e.name)}</strong></td><td>${esc(e.department)}</td><td>${esc(e.division)} / ${esc(e.job_title)}</td><td>${e.placement_level?'HSK '+e.placement_level:'Belum placement'}</td><td>${e.weekly.hsk?badge('Selesai · '+num(e.weekly.hsk.score),'green'):badge('Belum','gold')}</td><td>${e.weekly.work?badge('Selesai · '+num(e.weekly.work.score),'green'):badge('Belum','gold')}</td><td>${e.weekly.minutes} / 60 menit</td><td><a href="#employee/${e.id}">Lihat detail →</a></td></tr>`).join('')}</tbody></table></div>${employees.length?'':empty('Tidak ada karyawan sesuai filter')}`}</section><p class="weekly-note">Statistik nilai menggunakan periode ${date(d.period.start,true)} – ${date(d.period.end-1,true)}. Status misi dan waktu belajar menampilkan minggu berjalan. Aktivitas Leader tercatat sebagai penggunaan akun bersama.</p>`);applyProgress();form('#leader-filter',async fd=>{filters=Object.fromEntries(fd);await render();});bind('#export','click',async()=>{try{const r=await fetch('/api/leader/export?'+params);if(!r.ok)throw Error((await r.json()).error);const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='ecb-report.csv';a.click();URL.revokeObjectURL(url);}catch(e){toast(e.message);}});}await render();}
