async function route(){stopSpeech();cleanup();cleanup=()=>{};const version=++routeVersion;let [page,arg]=(location.hash.slice(1)||'').split('/');if(page==='recovery'&&window.recoveryToken){authView('recovery');return;}if(!user){authView(['register','forgot','recovery'].includes(page)?page:'login');return;}if(!page||['login','register','forgot'].includes(page)){location.hash=user.role==='leader'?'overview':'dashboard';return;}
 const allowed=user.role==='leader'?['learning-analytics','overview','employees','results','ranking','employee','exam']:['dashboard','learning','study','grammar','practice','story','speaking','package','examination','exam','ranking','profile','levelup','library','source'];if(!allowed.includes(page)){location.hash=user.role==='leader'?'overview':'dashboard';return;}
 if(['dashboard','learning','examination','ranking','profile','overview','employees','results','learning-analytics'].includes(page))shell(page,{dashboard:'Dashboard',learning:'Learning',examination:'Examination',ranking:'Ranking',profile:'Profile',overview:'Overview',employees:'Employees',results:'Results','learning-analytics':'Analitik Pembelajaran'}[page],'<section class="route-loading" role="status" aria-live="polite"><div class="route-skeleton"></div><p>Memuat halaman…</p></section>');
 try{if(page==='learning-analytics'){const {mountLearningAnalytics}=await import('./learning-analytics.js');await mountLearningAnalytics({api,shell,esc,root,cleanup:fn=>{cleanup=fn;}});}else if(page==='dashboard')await dashboard();else if(page==='learning')await learning();else if(['practice','story','speaking'].includes(page))await playPage(page,arg||'');else if(page==='study')await learning('study',arg);else if(page==='grammar')await learning('grammar',arg);else if(page==='package')await packagePage(arg);else if(page==='examination')await examination();else if(page==='levelup')await levelUpPage();else if(page==='exam')await examPage(arg);else if(page==='ranking')await ranking(arg||'');else if(page==='profile')await profile(arg==='edit');else if(page==='library')await libraryPage();else if(page==='source')await sourcePage(arg);else if(page==='employee')await employeePage(arg);else await leaderPage(page);}catch(e){if(version!==routeVersion)return;if(user)shell(page,'Informasi',heading('PORTAL ECB','Halaman belum dapat dimuat.','')+`<div class="notice error" role="alert">${esc(e.message)}</div><button class="btn" id="retry">Coba lagi</button>`);else authView();bind('#retry','click',route);}}
window.addEventListener('hashchange',route);
async function boot(){try{meta=await api('/meta');const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.get('type')==='recovery'&&fragment.get('access_token')){window.recoveryToken=fragment.get('access_token');history.replaceState(null,'','#recovery');}try{const me=await api('/me');user=me.user;csrf=me.csrf;}catch{}await route();}catch(e){root.innerHTML=empty('Server belum tersedia',e.message);}}
boot();
function parsed(value,fallback={}){try{return typeof value==='string'?JSON.parse(value):value||fallback;}catch{return fallback;}}
function sourceRef(value){return "";}

function wordExamples(value){const examples=parsed(value,[]);return examples.length?`<details class="source-examples"><summary>Contoh kalimat</summary>${examples.slice(0,2).map(e=>`<p lang="zh">${esc(e.zh)}</p>${speakButton(e.zh)}<p class="pinyin">${esc(e.pinyin)}</p><p>${esc(e.id)}</p>`).join('')}</details>`:'';}
function lessonHTML(lesson){const b=parsed(lesson.body),lines=v=>esc(v).replaceAll('\n','<br>');let body='';if(b.pattern)body=`<p><strong>Pola:</strong> ${lines(b.pattern)}</p><p>${lines(b.function)}</p><p lang="zh">${lines(b.examples_zh)}</p><p>${lines(b.examples_id)}</p>`;else if(b.paragraphs)body=b.paragraphs.map(p=>`<p>${lines(p)}</p>`).join('');else if(b.rows)body=b.rows.map(r=>`<div class="source-row">${r.cells.map(c=>`<p>${lines(c)}</p>`).join('')}</div>`).join('');return `<details class="panel source-lesson"><summary>${esc(lesson.title)} <span class="pill">${esc(lesson.kind)}</span></summary><div class="lesson-body"><div data-i18n-skip>${body}</div>${sourceRef(lesson.source_ref)}</div></details>`;}
async function libraryPage(){const viewVersion=routeVersion;const assets=await api('/library');let query='',track='',media='';function render(){const visible=assets.filter(a=>(!query||a.title.toLowerCase().includes(query.toLowerCase()))&&(!track||a.track===track)&&(!media||a.media_type===media));if(viewVersion!==routeVersion)return;shell('learning','Perpustakaan sumber',heading('SOURCE LIBRARY','Seluruh sumber, satu perpustakaan.','Workbook, dokumen, PDF dan audio Anda tetap memiliki asal dan versi yang jelas.','<a class="btn secondary" href="#learning">Kembali ke paket</a>')+`<div class="notice">Materi HSK 3.0 mengikuti level workbook sumber. PDF/MP3 ujian lama diberi label arsip; tidak diubah menjadi soal penentu level HSK 3.0. File dengan kerusakan yang belum dapat dipulihkan tetap terlihat dengan alasannya.</div><form id="library-filter" class="filters"><label>Cari sumber<input name="q" value="${esc(query)}" placeholder="Nama file, HSK, APD…"></label><label>Jalur<select name="track"><option value="">Semua sumber</option><option value="hsk" ${track==='hsk'?'selected':''}>HSK</option><option value="work" ${track==='work'?'selected':''}>Pekerjaan</option></select></label><label>Format<select name="media"><option value="">Semua format</option>${['xlsx','docx','pdf','mp3','zip'].map(m=>`<option ${m===media?'selected':''}>${m}</option>`).join('')}</select></label><button class="btn secondary" type="submit">Cari</button></form><p class="muted">${visible.length} dari ${assets.length} file sumber.</p><div class="package-grid">${visible.map(a=>{const d=parsed(a.detail);return `<article class="panel package"><div class="section-tag">${esc(a.media_type.toUpperCase())} · ${a.track==='hsk'?'HSK':'PEKERJAAN'}</div><h3 class="scroll-title">${esc(a.title)}</h3><p>${a.legacy?'Arsip HSK lama':a.level?'HSK 3.0 · Level '+a.level:'Kosakata & konteks pekerjaan'}${d.recovered?' · Worksheet dipulihkan':''}</p>${badge(a.status==='unreadable'?'Perlu file pengganti':a.legacy?'Arsip latihan':'Materi sumber',a.status==='unreadable'?'red':a.legacy?'gold':'green')}<a class="btn secondary mt" href="#source/${a.id}">Lihat sumber →</a></article>`;}).join('')}</div>`);form('#library-filter',async fd=>{query=fd.get('q');track=fd.get('track');media=fd.get('media');render();});}render();}
async function sourcePage(assetId){const viewVersion=routeVersion;const a=await api('/library/'+assetId),detail=parsed(a.detail);if(viewVersion!==routeVersion)return;shell('learning','Sumber materi',heading(a.legacy?'ARSIP LATIHAN':'MATERI SUMBER',a.title,a.legacy?'Sumber HSK versi lama, terpisah dari bank assessment HSK 3.0.':'Dokumen dan latihan pendukung pembelajaran.','<a class="btn secondary" href="#library">Semua sumber</a>')+`${a.status==='unreadable'?`<div class="notice error">${esc(detail.reason||'File belum dapat dibaca.')} Materi departemen tidak diganti dengan kosakata karangan.</div>`:detail.recovered?'<div class="notice">Worksheet dan data sumber dipulihkan dari arsip ZIP yang terpotong. File asli tidak diubah; pemulihan tercatat dalam laporan.</div>':''}${a.status==='available'&&a.media_type==='pdf'?`<section class="panel mb"><h2>Dokumen latihan</h2><p>${detail.pages||'—'} halaman. Baca sebagai latihan pelengkap; bukan sertifikasi atau kalibrasi level baru.</p><a class="btn" href="/api/library/${a.id}/file" target="_blank" rel="noopener">Buka PDF sumber ↗</a></section>`:''}${a.status==='available'&&a.media_type==='mp3'?`<section class="panel mb"><h2>Latihan mendengarkan</h2><audio controls preload="metadata" src="/api/library/${a.id}/file" class="w100">Browser Anda tidak mendukung audio.</audio><p class="weekly-note">Cari PDF dengan kode file yang sama dalam perpustakaan.</p></section>`:''}${['xlsx','docx'].includes(a.media_type)&&a.status==='available'?`<div class="notice">${detail.counts?.vocabulary||0} entri unik dipetakan dari sumber ini. Materi kosakata tersedia pada paket belajar; contoh, grammar dan bacaan ditampilkan di bawah bila tersedia. Workbook asli dengan kunci tidak dilayani sebagai file publik.</div><a class="btn secondary mb" href="#learning">Buka paket belajar →</a>${a.media_type==='docx'?'<a class="btn secondary mb" href="/api/library/'+a.id+'/file">Unduh dokumen asli & gambar ↓</a>':''}`:''}${a.media_type==='zip'?'<div class="notice">Arsip memuat sumber ujian lama. Gunakan PDF dan MP3 terpisah yang sudah tersedia pada perpustakaan.</div>':''}${a.lessons.map(lessonHTML).join('')}`);}
